-- Hyperpurex® EU-20UV ultrapure water system and its 7 consumables (8 products).
-- Run once in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug) values ('Hyperpurex', 'hyperpurex') on conflict (slug) do nothing;
insert into categories (name, slug, sort_order) values ('Equipment','equipment',5), ('Consumables','consumables',8) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('HYPERPUREX-EU-20UV', 'Hyperpurex EU-20UV Intelligent Ultrapure Water System', 'hyperpurex-eu-20uv-ultrapure-water-system', 'The Hyperpurex® EU-20UV is an intelligent, all-in-one ultrapure water system that takes tap water and produces 20 L/hour of ultrapure water (18.2 MΩ·cm, TOC 2 ppb), high-purity DI water and RO water. It has a 5-inch touch screen, a 35 L pure water tank and IoT cloud monitoring, and its water quality meets ASTM, GB/T, CP, EP, USP, JP, CAP and CLSI standards. Applications: HPLC, UPLC, LC-MS, ICP-MS, ICP-AES, AAS, GC-MS, IC, TOC analysis, microbial media, cell culture, PCR, IVF, protein work, and feed water for autoclaves and washers.', '[["Model", "EU-20UV (Low TOC)"], ["Series", "Hyperpurex® E Eminent Series"], ["Feed water", "Tap water"], ["Production rate", "20 L/hour"], ["Dispensing rate", "Up to 2 L/min"], ["Ultrapure (UP) water resistivity", "18.2 MΩ·cm at 25 °C (0.055 µS/cm)"], ["UP water TOC", "2 ppb"], ["UP water particles", "<1 /ml (>0.2 µm)"], ["UP water bacteria", "<0.01 CFU/ml"], ["DI water resistivity", ">16 MΩ·cm at 25 °C (0.063 µS/cm)"], ["RO water ion rejection", "98 – 99% (new RO module)"], ["RO organic rejection", ">99% (MW >300 Dalton)"], ["Feed water pressure", "1 – 6 bar"], ["Feed water temperature", "5 – 40 °C"], ["Feed water conductivity", "<2000 µS/cm"], ["Feed water hardness (CaCO₃)", "<300 ppm"], ["Feed water free chlorine", "<3 ppm"], ["Feed water pH", "4 – 10"], ["Pure water tank", "35 L"], ["Display", "5-inch IPS colour capacitive touch screen (Chinese / English)"], ["Connectivity", "USB, RJ45 or USB/WiFi, 4G; cloud platform; LIMS/BMS connection"], ["Data storage", "Up to 3 years of dispensing, alarm and cartridge records (Excel export)"], ["Power supply", "100 – 240 V, 50/60 Hz"], ["Total power", "120 W"], ["Dimensions (L × W × H)", "Main unit 370 × 623 × 600 mm; tank 392 × 518 × 630 mm"], ["Weight", "41 kg"], ["Standard configuration", "Main unit, full set of cartridges, water tank"], ["Standards met", "ASTM D1193-06, GB/T 11446.1-2013, GB/T 33087-2016, GB/T 6682-2008, CP, EP, USP, JP, CAP, CLSI"], ["Consumables", "HPC101, HPC102, HPC302, HPC501, HPC602 (×2), HPC703, HPC801"]]', '["Produces ultrapure (18.2 MΩ·cm), high-purity DI (>16 MΩ·cm) and RO water from tap water", "Dual-wavelength UV lamp (185 & 254 nm) reduces TOC to ≤2 ppb and sterilises", "DuPont RO membrane and resin; up to 4.08 L resin capacity for lower running cost", "3 water quality sensors and 2 flow sensors for quantitative dispensing", "Cartridge life shown with colour warnings; serial-number check for original cartridges", "IoT cloud platform via 4G or WiFi for remote monitoring and alarms", "Up to 5 optional HiDis dispenser arms; admin and user permission levels", "Alarms for no feed water, low pressure, full tank and water quality"]', '/products/hyperpurex/eu-20uv.jpg', 'equipment'),
  ('HYPERPUREX-HPC101', 'Hyperpurex HPC101 Pretreatment Cartridge A (PP)', 'hyperpurex-hpc101-pretreatment-cartridge-a-pp', '12-inch PP pretreatment cartridge with deep-folded membrane (5 µm) that filters particles from the feed water.', '[["Model", "HPC101"], ["For", "Hyperpurex® EU-20UV ultrapure water system"], ["Typical replacement", "about 13 months"], ["Filtration", "5 µm deep-folded PP membrane"]]', '[]', '/products/hyperpurex/cartridge-pp.jpg', 'consumables'),
  ('HYPERPUREX-HPC102', 'Hyperpurex HPC102 Pretreatment Cartridge B (PC)', 'hyperpurex-hpc102-pretreatment-cartridge-b-pc', '12-inch PC pretreatment cartridge with activated carbon fibre and catalyst (5 µm) that removes organics and residual chlorine without carbon dust.', '[["Model", "HPC102"], ["For", "Hyperpurex® EU-20UV ultrapure water system"], ["Typical replacement", "about 23 months"], ["Filtration", "5 µm activated carbon fibre with catalyst"]]', '[]', '/products/hyperpurex/cartridge-pc.jpg', 'consumables'),
  ('HYPERPUREX-HPC302', 'Hyperpurex HPC302 RO Module S2', 'hyperpurex-hpc302-ro-module-s2', 'Reverse osmosis module with DuPont membrane for long life and high ion rejection, packaged as one easy-to-replace unit.', '[["Model", "HPC302"], ["For", "Hyperpurex® EU-20UV ultrapure water system"], ["Typical replacement", "12 – 24 months"], ["Membrane", "DuPont RO membrane"], ["Ion rejection", "98 – 99%"]]', '[]', '/products/hyperpurex/cartridge-ro.jpg', 'consumables'),
  ('HYPERPUREX-HPC501', 'Hyperpurex HPC501 DI Cartridge', 'hyperpurex-hpc501-di-cartridge', 'DI pre-purification cartridge with DuPont ion-exchange resin (1.36 L) in a patented down-flow design that prevents resin stratification.', '[["Model", "HPC501"], ["For", "Hyperpurex® EU-20UV ultrapure water system"], ["Typical replacement", "2,600 L pure water per cartridge"], ["Resin", "DuPont ion-exchange resin, 1.36 L"]]', '[]', '/products/hyperpurex/cartridge-di.jpg', 'consumables'),
  ('HYPERPUREX-HPC602', 'Hyperpurex HPC602 UP Cartridge, Low TOC', 'hyperpurex-hpc602-up-cartridge-low-toc', 'Low-TOC ultrapure polishing cartridge with high-purity DuPont resin that delivers 18.2 MΩ·cm water with minimal TOC release.', '[["Model", "HPC602"], ["For", "Hyperpurex® EU-20UV ultrapure water system"], ["Typical replacement", "2,600 L pure water per cartridge (2 per system)"], ["Resin", "High-purity DuPont resin, 1.36 L"], ["Quantity per system", "2"]]', '[]', '/products/hyperpurex/cartridge-up.jpg', 'consumables'),
  ('HYPERPUREX-HPC703', 'Hyperpurex HPC703 Double Wavelength UV Lamp', 'hyperpurex-hpc703-double-wavelength-uv-lamp', 'Long-life dual-wavelength UV lamp (185 & 254 nm) in a SUS316L flow shell that lowers TOC to ≤2 ppb and inhibits bacterial growth.', '[["Model", "HPC703"], ["For", "Hyperpurex® EU-20UV ultrapure water system"], ["Typical replacement", "about 9,000 hours"], ["Wavelengths", "185 and 254 nm"], ["Flow shell", "SUS316L stainless steel"]]', '[]', '/products/hyperpurex/uv-lamp.jpg', 'consumables'),
  ('HYPERPUREX-HPC801', 'Hyperpurex HPC801 TF Terminal Microfilter', 'hyperpurex-hpc801-tf-terminal-microfilter', 'Terminal microfilter with double-layer (0.45 + 0.2 µm) PES membrane that retains microbes and particles at the water outlet.', '[["Model", "HPC801"], ["For", "Hyperpurex® EU-20UV ultrapure water system"], ["Typical replacement", "6 – 12 months"], ["Membrane", "Double-layer PES, 0.45 + 0.2 µm"]]', '[]', '/products/hyperpurex/terminal-microfilter.jpg', 'consumables')
) as v(sku, name, slug, description, specs, features, image_url, cat)
join categories c on c.slug = v.cat
cross join (select id from brands where slug = 'hyperpurex') b
on conflict (sku) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, specs = excluded.specs,
  features = excluded.features, category_id = excluded.category_id, brand_id = excluded.brand_id, image_url = excluded.image_url, is_active = true;

select name, sku from products where sku like 'HYPERPUREX-%' order by sku;
